import "@fontsource/roboto/latin-400.css";
export const otpDefaults = {"slotWidth":42,"slotHeight":44,"gap":6,"separatorWidth":8,"focusSlideDuration":260,"digitDuration":280,"shakeDuration":390,"clearDuration":180,"morphDuration":460} as const;
export const otpStyleHref = "kalos-otp-input-680f746ac1ee";
export const otpCss = ".kalos-otp{font:13px/20px Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", ByteSans, Arial, "Helvetica Neue", -apple-system, BlinkMacSystemFont, "noto sans", Helvetica, sans-serif;--otp-ink:rgba(0, 0, 0, 0.88);--otp-surface:#ffffff;--otp-shadow:0 0 0 0.5px rgba(0, 0, 0, 0.08), 0 1px 2px 0 rgba(0, 0, 0, 0.05);--otp-shadow-hover:0 0 0 0.5px rgba(0, 0, 0, 0.13), 0 1px 2px 0 rgba(0, 0, 0, 0.06);--otp-shadow-focus:0 0 0 1px rgba(0, 0, 0, 0.28), 0 1px 2px 0 rgba(0, 0, 0, 0.06);--otp-ease:cubic-bezier(0.22, 1, 0.36, 1);--otp-faint:rgba(0, 0, 0, 0.3);--otp-wash:rgba(0, 0, 0, 0.04);--otp-danger:#c4320a;--otp-danger-surface:rgba(240, 68, 56, 0.035);--otp-shadow-invalid:0 0 0 1px rgba(240, 68, 56, 0.55), 0 1px 2px 0 rgba(0, 0, 0, 0.05);--otp-shadow-invalid-focus:0 0 0 1px rgba(229, 72, 77, 0.8), 0 1px 2px 0 rgba(0, 0, 0, 0.05);--otp-success:#1e8a4f;--otp-muted:rgba(0, 0, 0, 0.61);--otp-slot-width:42px;--otp-height:44px;--otp-radius:7px;--otp-gap:6px;--otp-separator:8px;--otp-focus-in:80ms;--otp-focus-slide:260ms;--otp-digit-in:280ms;--otp-shake:390ms;--otp-clear:180ms;--otp-morph:460ms}
