.kalos-otp {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  max-width: 100%;
  min-width: 0;
  color: var(--otp-ink);
}

.kalos-otp[data-align="center"] { align-items: center; text-align: center; }
.kalos-otp__label { margin-bottom: 6px; }
.kalos-otp__stage {
  position: relative;
  --otp-code-width: calc(var(--otp-slot-width) * var(--otp-length) + var(--otp-gap) * (var(--otp-length) - 1) + var(--otp-extra));
  width: max(var(--otp-code-width), var(--otp-pill-width));
  max-width: 100%;
  min-width: 0;
  height: var(--otp-height);
}

.kalos-otp__row {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--otp-gap);
  width: min(100%, var(--otp-code-width));
  height: 100%;
  transition: opacity 200ms ease, transform 340ms var(--otp-ease);
}

.kalos-otp__row[data-disabled] { opacity: .4; }
.kalos-otp[data-align="center"] .kalos-otp__row { margin-inline: auto; }
.kalos-otp__slot {
  flex: 1 1 0;
  position: relative;
  display: grid;
  place-items: center;
  height: 100%;
  min-width: 0;
  isolation: isolate;
  border-radius: var(--otp-radius);
  background: var(--otp-surface);
  box-shadow: var(--otp-slot-shadow, var(--otp-shadow));
  transition: box-shadow 140ms var(--otp-ease), background-color 140ms var(--otp-ease);
}

.kalos-otp__slot:hover:not(:focus-within) { box-shadow: var(--otp-shadow-hover); }
.kalos-otp__slot:focus-within { --otp-slot-shadow: none; }
.kalos-otp__slot input {
  position: absolute;
  z-index: 1;
  inset: 0;
  width: 100%;
  height: 100%;
  appearance: none;
  border: 0;
  padding: 0;
  border-radius: inherit;
  outline: none;
  background: transparent;
  color: transparent;
  -webkit-text-fill-color: transparent;
  caret-color: transparent;
  text-align: center;
  font: inherit;
  font-size: 16px;
  font-variant-numeric: tabular-nums;
}
.kalos-otp__slot input::selection {
  /* The native slot stays ready for replacement while the visible digit keeps its regular appearance. */
  background: transparent;
  color: transparent;
}
.kalos-otp__slot input:-webkit-autofill { background-clip: text; }
.kalos-otp__digit {
  font-size: 16px;
  font-variant-numeric: tabular-nums;
  pointer-events: none;
  user-select: none;
  animation: kalos-otp-digit-in var(--otp-digit-in) var(--otp-ease) both;
  animation-delay: calc(var(--otp-slot-index) * 18ms);
}
.kalos-otp__caret {
  display: none;
  width: 1px;
  height: 16px;
  pointer-events: none;
  background: var(--otp-ink);
}
.kalos-otp__slot:has(input:focus:not([data-filled], [readonly])) .kalos-otp__caret {
  display: block;
  animation: kalos-otp-blink 1.1s ease-in-out infinite;
}
.kalos-otp__separator {
  flex: 0 0 var(--otp-separator);
  height: 1px;
  border-radius: 1px;
  background: var(--otp-faint);
}
.kalos-otp__ring {
  position: absolute;
  z-index: 2;
  inset: 0 auto 0 0;
  width: calc((100% - var(--otp-gap) * (var(--otp-length) - 1) - var(--otp-extra)) / var(--otp-length));
  border-radius: var(--otp-radius);
  box-shadow: var(--otp-shadow-focus);
  pointer-events: none;
  opacity: 0;
  transform: translateX(calc(var(--otp-active-index) * (100% + var(--otp-gap)) + var(--otp-active-extra)));
  transition: transform var(--otp-focus-slide) var(--otp-ease), opacity 140ms ease, box-shadow 140ms ease;
}
.kalos-otp__row:focus-within .kalos-otp__ring { opacity: 1; }
.kalos-otp__row:not(:focus-within) .kalos-otp__ring { transition-property: opacity, box-shadow; }
.kalos-otp__row[data-focus-enter] .kalos-otp__ring {
  transition: opacity var(--otp-focus-in) var(--otp-ease), box-shadow 140ms ease;
}

.kalos-otp[data-status="verifying"] .kalos-otp__slot { overflow: hidden; }
.kalos-otp[data-status="verifying"] .kalos-otp__slot::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(105deg, transparent 15%, var(--otp-wash) 50%, transparent 85%);
  animation: kalos-otp-shimmer 1.3s ease-in-out infinite;
  animation-delay: calc(var(--otp-slot-index) * 70ms);
}
.kalos-otp[data-error] .kalos-otp__slot {
  background: color-mix(in srgb, var(--otp-danger-surface), var(--otp-surface));
  box-shadow: var(--otp-slot-shadow, var(--otp-shadow-invalid));
}
.kalos-otp[data-error] .kalos-otp__ring { box-shadow: var(--otp-shadow-invalid-focus); }
.kalos-otp[data-error] .kalos-otp__caret { background: var(--otp-danger); }
.kalos-otp[data-error] .kalos-otp__row {
  animation: kalos-otp-shake var(--otp-shake) var(--otp-ease);
}
.kalos-otp__row[data-clearing] .kalos-otp__digit {
  animation: kalos-otp-digit-out var(--otp-clear) ease both;
  animation-delay: calc((var(--otp-length) - var(--otp-slot-index) - 1) * 15ms);
}
.kalos-otp__error {
  display: grid;
  grid-template-rows: 0fr;
  max-width: 100%;
  transition: grid-template-rows 260ms var(--otp-ease);
}
.kalos-otp__error[data-show] { grid-template-rows: 1fr; }
.kalos-otp__error > div { min-height: 0; overflow: hidden; }
.kalos-otp__error-text {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin: 9px 0 0;
  color: var(--otp-danger);
  opacity: 0;
  transform: translateY(-4px);
  transition: opacity 160ms ease, transform 260ms var(--otp-ease);
}
